FieldPixel:
param float cellScale = 6.0 [2.0, 16.0];
param float density = 40.0 [10.0, 100.0];
param float speed = 1.2 [0.0, 4.0];
param float drift = 0.05 [0.0, 0.3];
p = vec2(uv.x * aspect, uv.y);
cell = floor(p * cellScale);
hash = fract(sin(dot(cell, vec2(91.7, 57.3))) * 43758.5453);
ang = hash * 6.283185 + t * drift;
flowDir = vec2(cos(ang), sin(ang));
along = dot(p, flowDir);
streak = 0.5 + 0.5 * sin(along * density - t * speed);
col = vec3(streak * 0.85, streak * 0.55 + 0.1, 1.0 - streak * 0.6);

param float cellSize = 24.0 [6.0, 60.0];
param float contrast = 1.4 [0.5, 3.0];
p = vec2(uv.x * aspect, uv.y) * cellSize;
cell = floor(p);
f = fract(p) - 0.5;
lum = (col.r * 0.299 + col.g * 0.587 + col.b * 0.114) * contrast;
jitter = fract(sin(dot(cell, vec2(12.9898, 78.233))) * 43758.5453) * 0.15;
radius = sqrt(clamp(lum + jitter, 0.0, 1.0)) * 0.5;
edge = length(f) - radius;
dotMask = 1.0 - smoothstep(0.0, 0.03, edge);
col = vec3(dotMask);

param float cloudScale = 3.0 [1.0, 8.0];
param float swirl = 2.0 [0.0, 6.0];
param float speed = 0.3 [0.0, 2.0];
param float coreGlow = 1.0 [0.2, 2.5];
param float colorShift = 0.0 [0.0, 1.0];
param float starDensity = 40.0 [10.0, 120.0];
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
rad = length(p);
angle = atan2(p.y, p.x);
swirlAngle = angle + swirl * rad * 2.0 - t * speed * 0.5;
sp = vec2(cos(swirlAngle), sin(swirlAngle)) * rad;
freqA = cloudScale;
cA = sin(sp.x * freqA + t * speed) * cos(sp.y * freqA * 1.3 - t * speed * 0.7);
rB = vec2(sp.x * cos(0.65) - sp.y * sin(0.65), sp.x * sin(0.65) + sp.y * cos(0.65));
cB = sin(rB.x * freqA * 2.1 + t * speed * 1.4) * cos(rB.y * freqA * 1.7 - t * speed * 0.9);
rC = vec2(sp.x * cos(1.15) - sp.y * sin(1.15), sp.x * sin(1.15) + sp.y * cos(1.15));
cC = sin(rC.x * freqA * 3.7 + t * speed * 0.6) * cos(rC.y * freqA * 2.9 + t * speed * 1.1);
turb = (cA + 0.6 * cB + 0.35 * cC) / 1.95;
cloudVal = 0.5 + 0.5 * turb;
huey = cloudVal + colorShift;
cloudColor = vec3(0.5 + 0.5 * cos(6.283185 * (huey + 0.0)), 0.5 + 0.5 * cos(6.283185 * (huey + 0.33)), 0.5 + 0.5 * cos(6.283185 * (huey + 0.67)));
cloudColor = cloudColor * vec3(0.7, 0.5, 1.0);
col = cloudColor * (0.35 + 0.5 * cloudVal);
core = coreGlow * (0.15 / (rad * rad + 0.01));
glowTint = vec3(1.0, 0.9, 0.75);
col = col + glowTint * core * 0.15;
starP = vec2(uv.x * aspect, uv.y) * starDensity;
starCell = floor(starP);
starF = fract(starP) - 0.5;
starHash = fract(sin(dot(starCell, vec2(12.9898, 78.233))) * 43758.5453);
starHash2 = fract(sin(dot(starCell, vec2(39.346, 11.135))) * 53758.5453);
starOffset = vec2(starHash - 0.5, starHash2 - 0.5) * 0.7;
starDist = length(starF - starOffset);
starPresence = smoothstep(0.94, 1.0, starHash2);
twinkle = 0.5 + 0.5 * sin(t * 3.0 + starHash * 30.0);
starDot = (1.0 - smoothstep(0.0, 0.12, starDist)) * starPresence * (0.5 + 0.5 * twinkle);
col = col + vec3(1.0) * starDot;

param float scale = 3.0 [0.5, 8.0];
param float speed = 0.5 [0.05, 2.0];
param float warp = 1.5 [0.2, 4.0];
param float hue = 0.0 [0.0, 1.0];
p = vec2(uv.x * aspect, uv.y) * scale;
w1 = vec2(sin(p.y * 1.3 + t * speed), cos(p.x * 1.1 - t * speed * 0.8));
p1 = p + w1 * warp;
w2 = vec2(sin(p1.y * 1.7 - t * speed * 0.6), cos(p1.x * 1.5 + t * speed * 0.9));
p2 = p1 + w2 * warp * 0.6;
w3 = vec2(sin(p2.y * 2.1 + t * speed * 1.1), cos(p2.x * 1.9 - t * speed * 0.7));
p3 = p2 + w3 * warp * 0.35;
field1 = sin(p3.x * 1.3 + p3.y * 0.7);
field2 = cos(p3.x * 0.6 - p3.y * 1.4 + t * speed * 0.3);
liquid = field1 * 0.6 + field2 * 0.4;
pc = liquid * 0.5 + 0.5 + hue;
colA = vec3(0.5, 0.45, 0.55);
colB = vec3(0.45, 0.4, 0.5);
colC = vec3(1.0, 0.9, 0.7);
colD = vec3(0.1, 0.35, 0.55);
base = colA + colB * cos(6.283185 * (colC * pc + colD));
highlight = pow(clamp(liquid - 0.6, 0.0, 1.0) * 2.5, 3.0);
col = base + vec3(highlight);

param float scale = 3.0 [1, 8];
param float speed = 0.3 [0, 1.5];
param float warp  = 0.4 [0, 1.2];
param float hue   = 0.0 [0, 1];

p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5) * scale;

w1 = vec2(sin(p.y * 1.3 + t * speed * 1.1), cos(p.x * 1.3 - t * speed * 0.9));
p1 = p + w1 * warp;

w2 = vec2(sin(p1.y * 1.7 - t * speed * 0.8 + w1.x * 2.0), cos(p1.x * 1.7 + t * speed * 0.7 + w1.y * 2.0));
p2 = p1 + w2 * warp * 0.8;

w3 = vec2(sin(p2.y * 2.1 + t * speed * 0.6 - w2.x * 1.5), cos(p2.x * 2.1 - t * speed * 0.5 + w2.y * 1.5));
p3 = p2 + w3 * warp * 0.6;

field1 = 0.5 + 0.5 * sin(p3.x * 1.5 + p3.y * 1.5);
field2 = 0.5 + 0.5 * sin(length(p3) * 2.0 - t * speed);
liquid = field1 * 0.6 + field2 * 0.4;

pc = liquid + hue;
colA = vec3(0.5, 0.5, 0.6);
colB = vec3(0.5, 0.4, 0.4);
colC = vec3(1.0, 0.8, 0.6);
colD = vec3(0.0, 0.15, 0.35);
base = colA + colB * cos(6.283185 * (colC * pc + colD));

highlight = pow(max(liquid - 0.6, 0.0) * 2.5, 3.0);
col = base + vec3(highlight);

param float size  = 0.05 [0.02, 0.15];
param float speed = 0.35 [0, 1.5];

state float posX = 0;
state float posY = 0;
state float velX = 0;
state float velY = 0;

pos = vec2(posX, posY);
vel = vec2(velX, velY);

p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);

r0 = size;

posA = vec2(sin(t * 0.31 + 0.0) * 0.30 * aspect, cos(t * 0.47 + 0.0) * 0.30);
posB = vec2(cos(t * 0.23 + 1.7) * 0.32 * aspect, sin(t * 0.39 + 0.5) * 0.28);
posC = vec2(sin(t * 0.17 + 3.1) * 0.28 * aspect, cos(t * 0.29 + 2.2) * 0.32);
posD = vec2(cos(t * 0.41 + 0.9) * 0.22 * aspect, sin(t * 0.19 + 4.0) * 0.26);
posE = vec2(sin(t * 0.13 + 2.4) * 0.34 * aspect, cos(t * 0.53 + 1.1) * 0.20);
posF = vec2(cos(t * 0.37 + 5.2) * 0.18 * aspect, sin(t * 0.11 + 0.3) * 0.30);
posG = vec2(sin(t * 0.27 + 3.7) * 0.30 * aspect, cos(t * 0.43 + 2.9) * 0.24);
posH = vec2(cos(t * 0.19 + 1.1) * 0.26 * aspect, sin(t * 0.31 + 3.6) * 0.33);

rA = size * 0.75; rB = size * 1.3; rC = size * 0.55; rD = size * 1.1;
rE = size * 0.65; rF = size * 0.9;  rG = size * 1.2;  rH = size * 0.7;

first = 1.0 - step(0.5, age);
s0 = t + 11.0;
hx0 = fract(sin(s0 * 12.9898) * 43758.5453);
hy0 = fract(sin(s0 * 78.233) * 43758.5453);
ha0 = fract(sin(s0 * 37.719) * 24634.6345);

pos = mix(pos, vec2((hx0 - 0.5) * (aspect - 2.0 * r0), (hy0 - 0.5) * (1.0 - 2.0 * r0)), first);
vel = mix(vel, vec2(cos(ha0 * 6.283185), sin(ha0 * 6.283185)), first);

pos += vel * dt * speed;

xl = aspect * 0.5 - r0; yl = 0.5 - r0;
vel.x = mix(vel.x, -vel.x, max(step(xl, pos.x), step(pos.x, -xl)));
vel.y = mix(vel.y, -vel.y, max(step(yl, pos.y), step(pos.y, -yl)));
pos = clamp(pos, vec2(-xl, -yl), vec2(xl, yl));

dxA = pos.x - posA.x; dyA = pos.y - posA.y;
oA = (r0 + rA) - sqrt(dxA * dxA + dyA * dyA);
cA = step(0.0, oA);
lenA = sqrt(dxA * dxA + dyA * dyA) + 0.0008;
nA = vec2(dxA / lenA, dyA / lenA);
vdA = vel.x * nA.x + vel.y * nA.y;
vel = mix(vel, vel - 2.0 * vdA * nA, cA);
pos += nA * (0.5 * oA * cA);

dxB = pos.x - posB.x; dyB = pos.y - posB.y;
oB = (r0 + rB) - sqrt(dxB * dxB + dyB * dyB);
cB = step(0.0, oB);
lenB = sqrt(dxB * dxB + dyB * dyB) + 0.0008;
nB = vec2(dxB / lenB, dyB / lenB);
vdB = vel.x * nB.x + vel.y * nB.y;
vel = mix(vel, vel - 2.0 * vdB * nB, cB);
pos += nB * (0.5 * oB * cB);

dxC = pos.x - posC.x; dyC = pos.y - posC.y;
oC = (r0 + rC) - sqrt(dxC * dxC + dyC * dyC);
cC = step(0.0, oC);
lenC = sqrt(dxC * dxC + dyC * dyC) + 0.0008;
nC = vec2(dxC / lenC, dyC / lenC);
vdC = vel.x * nC.x + vel.y * nC.y;
vel = mix(vel, vel - 2.0 * vdC * nC, cC);
pos += nC * (0.5 * oC * cC);

dxD = pos.x - posD.x; dyD = pos.y - posD.y;
oD = (r0 + rD) - sqrt(dxD * dxD + dyD * dyD);
cD = step(0.0, oD);
lenD = sqrt(dxD * dxD + dyD * dyD) + 0.0008;
nD = vec2(dxD / lenD, dyD / lenD);
vdD = vel.x * nD.x + vel.y * nD.y;
vel = mix(vel, vel - 2.0 * vdD * nD, cD);
pos += nD * (0.5 * oD * cD);

dxE = pos.x - posE.x; dyE = pos.y - posE.y;
oE = (r0 + rE) - sqrt(dxE * dxE + dyE * dyE);
cE = step(0.0, oE);
lenE = sqrt(dxE * dxE + dyE * dyE) + 0.0008;
nE = vec2(dxE / lenE, dyE / lenE);
vdE = vel.x * nE.x + vel.y * nE.y;
vel = mix(vel, vel - 2.0 * vdE * nE, cE);
pos += nE * (0.5 * oE * cE);

dxF = pos.x - posF.x; dyF = pos.y - posF.y;
oF = (r0 + rF) - sqrt(dxF * dxF + dyF * dyF);
cF = step(0.0, oF);
lenF = sqrt(dxF * dxF + dyF * dyF) + 0.0008;
nF = vec2(dxF / lenF, dyF / lenF);
vdF = vel.x * nF.x + vel.y * nF.y;
vel = mix(vel, vel - 2.0 * vdF * nF, cF);
pos += nF * (0.5 * oF * cF);

dxG = pos.x - posG.x; dyG = pos.y - posG.y;
oG = (r0 + rG) - sqrt(dxG * dxG + dyG * dyG);
cG = step(0.0, oG);
lenG = sqrt(dxG * dxG + dyG * dyG) + 0.0008;
nG = vec2(dxG / lenG, dyG / lenG);
vdG = vel.x * nG.x + vel.y * nG.y;
vel = mix(vel, vel - 2.0 * vdG * nG, cG);
pos += nG * (0.5 * oG * cG);

dxH = pos.x - posH.x; dyH = pos.y - posH.y;
oH = (r0 + rH) - sqrt(dxH * dxH + dyH * dyH);
cH = step(0.0, oH);
lenH = sqrt(dxH * dxH + dyH * dyH) + 0.0008;
nH = vec2(dxH / lenH, dyH / lenH);
vdH = vel.x * nH.x + vel.y * nH.y;
vel = mix(vel, vel - 2.0 * vdH * nH, cH);
pos += nH * (0.5 * oH * cH);

posX = pos.x; posY = pos.y;
velX = vel.x; velY = vel.y;

in0 = step(length(p - pos), r0);
inA = step(length(p - posA), rA);
inB = step(length(p - posB), rB);
inC = step(length(p - posC), rC);
inD = step(length(p - posD), rD);
inE = step(length(p - posE), rE);
inF = step(length(p - posF), rF);
inG = step(length(p - posG), rG);
inH = step(length(p - posH), rH);

bw = mod(in0 + inA + inB + inC + inD + inE + inF + inG + inH, 2.0);
col = vec3(bw);

param float speed = 0.35 [0, 2];
param float freq  = 14.0 [2, 40];
param float arms  = 9.0  [1, 24];
param float warp  = 0.5  [0, 2];
param float rate  = 0.08 [0.01, 1];

state float A = 0 [wrap];

p   = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
rad = length(p) + 0.0008;
ang = atan2(p.y, p.x);

fb = A(uv + p * warp * 0.05);

wave    = sin(rad * freq - t * speed * 6.283185 + fb * 6.283185);
pattern = sin(ang * arms + wave * 3.0);
bw      = step(0.0, pattern);

A = mix(A, bw, rate);

col = vec3(bw);

param float speed = 1.0 [0.0, 5.0];
param float freq = 10.0 [1.0, 30.0];
param float arms = 5.0 [1.0, 12.0];
param float warp = 1.0 [0.0, 3.0];
param float rate = 0.9 [0.5, 0.999];
state float A = 0 [wrap];
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
d = length(p);
ang = atan2(p.y, p.x);
spiral = sin(ang * arms + d * freq - t * speed);
fresh = step(0.0, spiral);
prev = A(uv + p * warp * 0.05);
A = clamp(fresh * 0.5 + prev * rate, 0.0, 1.0);
bw = step(0.5, A);
col = vec3(bw);

param float speed = 1.5 [0.1, 6.0];
param float saturation = 0.8 [0.0, 1.0];
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
d = length(p);
angle = atan2(p.y, p.x);
hue = fract(angle / 6.283185 + t * 0.1 * speed);
r = clamp(abs(fract(hue + 1.0) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
g = clamp(abs(fract(hue + 0.6666) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
b = clamp(abs(fract(hue + 0.3333) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
rgb = mix(vec3(1.0), vec3(r, g, b), saturation);
col = rgb * (0.6 + 0.4 * sin(d * 20.0 - t * speed));
